mapper.select:
SELECT id, job_id, run_id, step_id, change_set_id, user_id,
       project_id, shot_id, provider, config_id, status, provider_job_id,
       progress, cancel_requested, error_code, error_message, owner_instance_id, owner_epoch,
       lease_until, attempts, next_action_at, submitted_at, finished_at, reconciled_by,
       reconciled_at, reconciliation_note, created_at, updated_at, created_by, updated_by
FROM manga_generation_job
WHERE user_id = #{userId} AND project_id = #{projectId}
AND run_id = #{runId}

    AND EXISTS (SELECT 1 FROM manga_creative_run r WHERE r.run_id = manga_generation_job.run_id
                AND r.conversation_id = #{conversationId})

AND id < #{beforeId}
ORDER BY id DESC LIMIT #{limit}

SELECT COUNT(*) FROM manga_generation_job
WHERE provider = #{provider}
  AND status IN ('SUBMITTING', 'SUBMITTED', 'RUNNING', 'MATERIALIZING', 'UNKNOWN')
AND user_id = #{userId}
